use std::io::{self, BufRead};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Priority {
    High,
    Normal,
    Low,
}

impl Priority {
    fn name(self) -> &'static str {
        match self {
            Priority::High => "high",
            Priority::Normal => "normal",
            Priority::Low => "low",
        }
    }
}

#[derive(Debug)]
struct Task {
    id: u32,
    text: String,
    priority: Priority,
    done: bool,
}

struct TodoList {
    tasks: Vec<Task>,
    next_id: u32,
}

impl TodoList {
    fn new() -> TodoList {
        TodoList { tasks: Vec::new(), next_id: 1 }
    }

    fn add(&mut self, text: &str, priority: Priority) -> u32 {
        let id = self.next_id;
        self.next_id += 1;
        self.tasks.push(Task { id, text: text.to_string(), priority, done: false });
        id
    }

    fn find_mut(&mut self, id: u32) -> Option<&mut Task> {
        for task in self.tasks.iter_mut() {
            if task.id == id {
                return Some(task);
            }
        }
        None
    }

    fn complete(&mut self, id: u32) -> Result<String, String> {
        let Some(task) = self.find_mut(id) else {
            return Err(format!("No task #{id}"));
        };
        if task.done {
            return Ok(format!("#{id} is already done"));
        }
        task.done = true;
        Ok(format!("Completed #{id}"))
    }

    fn reopen(&mut self, id: u32) -> Result<String, String> {
        let Some(task) = self.find_mut(id) else {
            return Err(format!("No task #{id}"));
        };
        if !task.done {
            return Ok(format!("#{id} is not done"));
        }
        task.done = false;
        Ok(format!("Reopened #{id}"))
    }

    fn remove(&mut self, id: u32) -> Result<String, String> {
        for (index, task) in self.tasks.iter().enumerate() {
            if task.id == id {
                self.tasks.remove(index);
                return Ok(format!("Removed #{id}"));
            }
        }
        Err(format!("No task #{id}"))
    }

    fn lines(&self) -> Vec<String> {
        let mut open: Vec<&Task> = Vec::new();
        let mut done: Vec<&Task> = Vec::new();
        for task in &self.tasks {
            if task.done {
                done.push(task);
            } else {
                open.push(task);
            }
        }
        open.sort_by_key(|t| (t.priority, t.id));
        let mut lines = Vec::new();
        for t in open {
            lines.push(format!("[ ] #{} ({}) {}", t.id, t.priority.name(), t.text));
        }
        for t in done {
            lines.push(format!("[x] #{} ({}) {}", t.id, t.priority.name(), t.text));
        }
        lines
    }

    fn stats(&self) -> String {
        let mut done = 0;
        let mut high = 0;
        for t in &self.tasks {
            if t.done {
                done += 1;
            } else if t.priority == Priority::High {
                high += 1;
            }
        }
        let open = self.tasks.len() - done;
        format!("{} tasks: {done} done, {open} open ({high} high)", self.tasks.len())
    }
}

fn parse_id(text: &str) -> Result<u32, String> {
    match text.parse() {
        Ok(id) => Ok(id),
        Err(_) => Err(format!("Not a number: {text}")),
    }
}

fn main() {
    let mut list = TodoList::new();
    for line in io::stdin().lock().lines() {
        let line = line.unwrap();
        let words: Vec<&str> = line.split_whitespace().collect();
        if words.is_empty() {
            continue;
        }
        let command_text = words[0].to_lowercase();
        let command: &str = &command_text;
        let result: Result<String, String> = match command {
            "quit" => break,
            "add" => {
                let second = if words.len() > 1 { words[1].to_lowercase() } else { String::new() };
                let (priority, start) = if second == "high" {
                    (Priority::High, 2)
                } else if second == "low" {
                    (Priority::Low, 2)
                } else {
                    (Priority::Normal, 1)
                };
                if words.len() <= start {
                    Err("Usage: add [high|low] <text>".to_string())
                } else {
                    let text = words[start..].join(" ");
                    let id = list.add(&text, priority);
                    Ok(format!("Added #{id}: {text}"))
                }
            }
            "done" | "undo" | "remove" => {
                if words.len() < 2 {
                    Err(format!("Usage: {command} <id>"))
                } else {
                    match parse_id(words[1]) {
                        Err(message) => Err(message),
                        Ok(id) => match command {
                            "done" => list.complete(id),
                            "undo" => list.reopen(id),
                            _ => list.remove(id),
                        },
                    }
                }
            }
            "list" => {
                let lines = list.lines();
                if lines.is_empty() { Ok("Nothing to do.".to_string()) } else { Ok(lines.join("\n")) }
            }
            "stats" => Ok(list.stats()),
            _ => Err(format!("Unknown command: {}", words[0])),
        };
        match result {
            Ok(text) => println!("{text}"),
            Err(text) => println!("{text}"),
        }
    }
}
